import { resend } from "@/lib/resend";
import { WelcomeEmail } from "@/emails/welcome";
import { PasswordResetEmail } from "@/emails/password-reset";
import type { User } from "@/lib/users";

const appUrl = () => process.env.NEXT_PUBLIC_APP_URL ?? "http://localhost:3000";

// Resend resolves to { error } instead of throwing; log it so a failed email
// never breaks the request that triggered it.
async function send(label: string, payload: Parameters<typeof resend.emails.send>[0]) {
  try {
    const { error } = await resend.emails.send(payload);
    if (error) console.error(`[email] ${label} failed: ${error.name}: ${error.message}`);
  } catch (err) {
    console.error(`[email] ${label} failed`, err);
  }
}

export async function sendWelcomeEmail(user: User) {
  await send("welcome", {
    from: process.env.RESEND_FROM_EMAIL!,
    to: user.email,
    subject: "Welcome to Notely",
    react: WelcomeEmail({ name: user.name, appUrl: appUrl() }),
  });
}

export async function sendPasswordResetEmail(user: User, token: string) {
  const actionUrl = `${appUrl()}/reset-password?token=${encodeURIComponent(token)}`;
  await send("password reset", {
    from: process.env.RESEND_FROM_EMAIL!,
    to: user.email,
    subject: "Reset your Notely password",
    react: PasswordResetEmail({ name: user.name, actionUrl }),
  });
}
EOF
cat >> src/lib/users.ts <<'EOF'

export async function createUser(input: { email: string; name: string }): Promise<User> {
  const email = input.email.trim().toLowerCase();
  if (users.some((u) => u.email === email)) {
    throw new Error("A user with this email already exists");
  }
  const user: User = {
    id: String(users.length + 1),
    email,
    name: input.name.trim(),
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  await sendWelcomeEmail(user);
  return user;
}

const RESET_TTL_MS = 60 * 60 * 1000;
// token hash -> reset request. Hashed so a leaked store can't be used to reset passwords.
const resetTokens = new Map<string, { userId: string; expiresAt: number }>();

const hashToken = (token: string) => createHash("sha256").update(token).digest("hex");

// Always resolves without revealing whether the email is registered.
export async function requestPasswordReset(email: string): Promise<void> {
  const normalized = email.trim().toLowerCase();
  const user = users.find((u) => u.email === normalized);
  if (!user) return;
  const token = randomBytes(32).toString("base64url");
  resetTokens.set(hashToken(token), { userId: user.id, expiresAt: Date.now() + RESET_TTL_MS });
  await sendPasswordResetEmail(user, token);
}

// Returns the user a valid token belongs to and consumes it (single use).
export async function consumePasswordResetToken(token: string): Promise<User | undefined> {
  const key = hashToken(token);
  const entry = resetTokens.get(key);
  resetTokens.delete(key);
  if (!entry || entry.expiresAt < Date.now()) return undefined;
  return getUser(entry.userId);
}
EOF
